const int res = 64;

int hash(int key_f)
{
    int key = int(key_f * 1000000);
    if (key == 0)
        return 0;

    int hash = 2166136261;
    const int prime = 16777619;

    for (int i = 0; i < 32; i++) {
        hash ^= key % 16;
        hash *= prime;
        key /= 16;
    }

    return hash;
}

float qrcode(vec2 uv) {
    int x = int(uv.x * float(res));
    int y = int(uv.y * float(res));
    int h = hash(x);
    float random = float((h % 2) ^ (hash((x + h + 1) * (y + 1)) % 2));

    int x_ = res - x - 1;
    int y_ = res - y - 1;
    if (x < 10 && y_ < 10) {
        int dx = abs(x - 4);
        int dy = abs(y_ - 4);
        if (dx < 4 && dy < 4)
            return dx < 3 && dy < 3 ? 0. : 1.;
        return dx < 5 && dy < 5 ? 0. : 1.;
    }
    if (x_ < 10 && y_ < 10) {
        int dx = abs(x_ - 4);
        int dy = abs(y_ - 4);
        if (dx < 4 && dy < 4)
            return dx < 3 && dy < 3 ? 0. : 1.;
        return dx < 5 && dy < 5 ? 0. : 1.;
    }
    if (x < 10 && y < 10) {
        int dx = abs(x - 4);
        int dy = abs(y - 4);
        if (dx < 4 && dy < 4)
            return dx < 3 && dy < 3 ? 0. : 1.;
        return dx < 5 && dy < 5 ? 0. : 1.;
    }
    if (x_ > 2 && y > 2 && x_ - 4 < 6 && y - 4 < 6) {
        int dx = abs(x_ - 6);
        int dy = abs(y - 6);
        if (dx < 2 && dy < 2)
            return dx == 0 && dy == 0 ? 0. : 1.;
        return dx < 3 && dy < 3 ? 0. : 1.;
    }
    return random;
}

float smooth_qrcode(vec2 uv) {
    int n = int(iResolution.y / float(res) * .25);

    float diff = 1. / iResolution.y;
    int count = 0;
    for (int x = -n; x <= n; x++)
    for (int y = -n; y <= n; y++)
        count += qrcode(vec2(uv.x + float(x) * diff, uv.y + float(y) * diff)) > .5 ? 1 : 0;

    return float(count) < pow(2. * float(n) + 1., 2.) / 2. ? 0. : 1.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv.x = uv.x * iResolution.x / iResolution.y - (iResolution.x - iResolution.y) / iResolution.y / 2.;

    float threshold = (sin(iTime * .5) + 1.) * .25 + .25;
    float x = abs(uv.x - threshold) < .002 ? .5 : uv.x < 0. || uv.x > 1. ? .7 : uv.x < threshold ? qrcode(uv) : smooth_qrcode(uv);
    fragColor = vec4(x, x, x, 1.);
}
